CREATE TABLE public.supabase_oauth_connections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL UNIQUE REFERENCES auth.users(id) ON DELETE CASCADE,access_token text,refresh_token text,token_expires_at bigint,organizations jsonb NOT NULL DEFAULT '[]',projects jsonb NOT NULL DEFAULT '[]',selected_project_id text,selected_project_name text,selected_project_url text,is_connected boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE,DELETE ON public.supabase_oauth_connections TO authenticated; GRANT ALL ON public.supabase_oauth_connections TO service_role; ALTER TABLE public.supabase_oauth_connections ENABLE ROW LEVEL SECURITY; CREATE POLICY "own supabase oauth connection" ON public.supabase_oauth_connections FOR ALL USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE TABLE public.client_greeted(user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,page_id text NOT NULL,sender_id text NOT NULL,greeted_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,page_id,sender_id)); GRANT SELECT,INSERT,UPDATE,DELETE ON public.client_greeted TO authenticated; GRANT ALL ON public.client_greeted TO service_role; ALTER TABLE public.client_greeted ENABLE ROW LEVEL SECURITY; CREATE POLICY "own client_greeted" ON public.client_greeted FOR ALL USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE TABLE public.push_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,token text NOT NULL UNIQUE,user_agent text,enabled boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE,DELETE ON public.push_tokens TO authenticated; GRANT ALL ON public.push_tokens TO service_role; ALTER TABLE public.push_tokens ENABLE ROW LEVEL SECURITY; CREATE POLICY "own push_tokens" ON public.push_tokens FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE TABLE public.push_settings(user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,auto_ai_enabled boolean NOT NULL DEFAULT true,updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE,DELETE ON public.push_settings TO authenticated; GRANT ALL ON public.push_settings TO service_role; ALTER TABLE public.push_settings ENABLE ROW LEVEL SECURITY; CREATE POLICY "own push_settings" ON public.push_settings FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE TABLE public.push_dispatch_log(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slot_key text NOT NULL UNIQUE,title text,body text,sent_count integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now()); GRANT ALL ON public.push_dispatch_log TO service_role; ALTER TABLE public.push_dispatch_log ENABLE ROW LEVEL SECURITY; CREATE POLICY "service manages push_dispatch_log" ON public.push_dispatch_log FOR ALL TO service_role USING(true) WITH CHECK(true);
CREATE TABLE public.comment_violations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,page_id text NOT NULL,author_id text NOT NULL,author_name text,offense_count integer NOT NULL DEFAULT 1,last_reason text,banned boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(page_id,author_id)); GRANT SELECT,INSERT,UPDATE,DELETE ON public.comment_violations TO authenticated; GRANT ALL ON public.comment_violations TO service_role; ALTER TABLE public.comment_violations ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users manage their own comment violations" ON public.comment_violations FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE TRIGGER trg_soc_updated BEFORE UPDATE ON public.supabase_oauth_connections FOR EACH ROW EXECUTE FUNCTION public.set_updated_at(); CREATE TRIGGER trg_comment_violations_updated BEFORE UPDATE ON public.comment_violations FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$BEGIN INSERT INTO public.profiles(id,email,display_name,avatar_url) VALUES(NEW.id,NEW.email,COALESCE(NEW.raw_user_meta_data->>'full_name',NEW.raw_user_meta_data->>'name',NEW.email),NEW.raw_user_meta_data->>'avatar_url'); INSERT INTO public.settings(user_id) VALUES(NEW.id) ON CONFLICT DO NOTHING; INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'admin') ON CONFLICT DO NOTHING; RETURN NEW; END$$; REVOKE EXECUTE ON FUNCTION public.handle_new_user() FROM PUBLIC,anon,authenticated; CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();
CREATE OR REPLACE FUNCTION public.verify_facebook_webhook_token(_token text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT EXISTS(SELECT 1 FROM public.settings WHERE facebook_verify_token=btrim(_token) AND facebook_verify_token IS NOT NULL AND btrim(facebook_verify_token)<>'')$$; REVOKE ALL ON FUNCTION public.verify_facebook_webhook_token(text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.verify_facebook_webhook_token(text) TO service_role;
ALTER PUBLICATION supabase_realtime ADD TABLE public.profiles; ALTER PUBLICATION supabase_realtime ADD TABLE public.facebook_pages;
CREATE POLICY "post_images_select_own" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='post-images' AND(storage.foldername(name))[1]=auth.uid()::text); CREATE POLICY "post_images_insert_own" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='post-images' AND(storage.foldername(name))[1]=auth.uid()::text); CREATE POLICY "post_images_update_own" ON storage.objects FOR UPDATE TO authenticated USING(bucket_id='post-images' AND(storage.foldername(name))[1]=auth.uid()::text); CREATE POLICY "post_images_delete_own" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='post-images' AND(storage.foldername(name))[1]=auth.uid()::text);
