CREATE POLICY "product img own read" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='product-images' AND(storage.foldername(name))[1]=auth.uid()::text); CREATE POLICY "product img own write" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='product-images' AND(storage.foldername(name))[1]=auth.uid()::text); CREATE POLICY "product img own delete" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='product-images' AND(storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY "post-videos owner select" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='post-videos' AND(storage.foldername(name))[1]=auth.uid()::text); CREATE POLICY "post-videos owner insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='post-videos' AND(storage.foldername(name))[1]=auth.uid()::text); CREATE POLICY "post-videos owner update" ON storage.objects FOR UPDATE TO authenticated USING(bucket_id='post-videos' AND(storage.foldername(name))[1]=auth.uid()::text); CREATE POLICY "post-videos owner delete" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='post-videos' AND(storage.foldername(name))[1]=auth.uid()::text);